        yield* sql`SELECT * FROM effect_sql_migrations ORDER BY migration_id`,
        history,
      );
      assert.deepEqual(yield* sql`SELECT * FROM t3code_fork_migrations`, []);
    }).pipe(Effect.provide(NodeSqliteClient.layerMemory())),
);

